#include <algorithm>
#include <chrono>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <unordered_map>
#include <vector>
#include <tuple>
using namespace std;using Row=vector<pair<int,int>>;struct Trace{int kind,src,a,b,ma,mb,norm;vector<tuple<int,int,int>>steps;};
int main(int argc,char**argv){if(argc!=7)return 1;auto start=chrono::steady_clock::now();ifstream raw(argv[1]),tr(argv[2]),selected(argv[3]),old(argv[4]);ofstream out(argv[5],ios::binary),meta(argv[6]);if(!raw||!tr||!selected||!old||!out||!meta)return 2;int p,n,N,F;raw>>p>>n>>N>>F;if(p!=32003||n!=11)return 3;vector<int>degree(N);for(int&d:degree)raw>>d;vector<uint64_t>keys(N,UINT64_MAX);keys[0]=0;for(int j=0;j<n;j++){vector<int>line(N);for(int&k:line)raw>>k;for(int i=0;i<N;i++)if(line[i]>=0){uint64_t k=keys[i];if(k==UINT64_MAX){/* reconstructed after reading all maps below */}}}
// The input monomial order is fixed degree/CWR, so generate keys directly.
keys.clear();auto rec=[&](auto&&self,int left,int first,uint64_t key,int vars,vector<uint64_t>&out)->void{if(!left){out.push_back(key);return;}for(int j=first;j<vars;j++)self(self,left-1,j,key+(1ULL<<(4*j)),vars,out);};int D=*max_element(degree.begin(),degree.end());for(int d=0;d<=D;d++)rec(rec,d,0,0,11,keys);if((int)keys.size()!=N||D!=10)return 4;
vector<uint64_t>normal,base;vector<int>nd,bd;for(int d=0;d<=D;d++){int before=normal.size();rec(rec,d,0,0,8,normal);for(int j=before;j<(int)normal.size();j++)nd.push_back(d);}for(int d=0;d<=3;d++){int before=base.size();rec(rec,d,0,0,3,base);for(int j=before;j<(int)base.size();j++)bd.push_back(d);}unordered_map<uint64_t,int>ni,ui;for(int i=0;i<(int)normal.size();i++)ni[normal[i]]=i;for(int i=0;i<(int)base.size();i++)ui[base[i]]=i;int nf;selected>>nf;vector<int>source(nf);unordered_map<int,int>sourceIndex;for(int j=0;j<nf;j++){selected>>source[j];sourceIndex[source[j]]=j;}int keepCount;selected>>keepCount;vector<int>keep(keepCount);for(int&i:keep)selected>>i;
vector<vector<Row>>inputs(20,vector<Row>(nf));for(int row=0;row<F;row++){int len;raw>>len;for(int z=0;z<len;z++){int k,c;raw>>k>>c;if(!sourceIndex.count(row))continue;uint64_t u=keys[k]>>32,x=keys[k]&0xffffffffULL;if(!ui.count(u))return 5;inputs[ui.at(u)][sourceIndex.at(row)].emplace_back(ni.at(x),c);}}vector<int>observable(N);for(int&c:observable)raw>>c;if(!raw)return 6;
int nodes;tr>>nodes;vector<Trace>trace(nodes);for(auto&t:trace){int count;tr>>t.kind>>t.src>>t.a>>t.b>>t.ma>>t.mb>>t.norm>>count;for(int j=0;j<count;j++){int a,b,c;tr>>a>>b>>c;t.steps.emplace_back(a,b,c);}}if(!tr)return 7;int oldN,oldB;old>>oldN>>oldB;if(oldB!=nodes)return 8;vector<Row>oldBasis(nodes);for(auto&r:oldBasis){int len;old>>len;for(int j=0;j<len;j++){int a,b;old>>a>>b;r.emplace_back(a,b);}}if(!old)return 9;
auto write=[&](int x){out.write(reinterpret_cast<const char*>(&x),sizeof x);};write(32003);write(D);write(20);write(keepCount);for(int j:keep)write(j);
for(int u=0;u<20;u++){int DD=D-bd[u],NN=upper_bound(nd.begin(),nd.end(),DD)-nd.begin();vector<Row>basis;basis.reserve(nodes);unordered_map<uint64_t,Row>cache;long cacheTerms=0;auto add=[&](vector<uint64_t>&v,int parent,int mul,int c){uint64_t ck=(uint64_t(parent)<<32)|uint32_t(mul);auto it=cache.find(ck);if(it==cache.end()){Row r;int md=nd[mul];for(auto[j,a]:basis[parent])if(nd[j]+md<=DD)r.emplace_back(ni.at(normal[j]+normal[mul]),a);if(cacheTerms+(long)r.size()>100000000){cache.clear();cacheTerms=0;}cacheTerms+=r.size();it=cache.emplace(ck,std::move(r)).first;}for(auto[j,a]:it->second)v[j]+=uint64_t(c)*uint64_t(a);};
for(int id=0;id<nodes;id++){auto&t=trace[id];vector<uint64_t>v(NN);if(t.kind==0){for(auto[j,c]:inputs[u][t.src])if(j<NN)v[j]=c;}else{if(t.a>=id||t.b>=id)return 10;add(v,t.a,t.ma,1);add(v,t.b,t.mb,32002);}for(auto[parent,mul,c]:t.steps){if(parent>=id)return 11;add(v,parent,mul,c);}Row r;for(int j=0;j<NN;j++){int c=(v[j]%32003)*t.norm%32003;if(c)r.emplace_back(j,c);}if(u==0){Row shortrow;for(auto[j,c]:r)if(j<oldN)shortrow.emplace_back(j,c);if(shortrow!=oldBasis[id]){cerr<<"old mismatch "<<id<<"\n";return 12;}}basis.push_back(std::move(r));if(id%20==0)cerr<<"NODE "<<u<<" "<<id<<" cacheTerms "<<cacheTerms<<" seconds "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<"\n";}
write(u);write(NN);long terms=0;for(int id:keep){write(basis[id].size());for(auto[j,c]:basis[id]){write(j);write(c);}terms+=basis[id].size();}out.flush();if(!out)return 13;double sec=chrono::duration<double>(chrono::steady_clock::now()-start).count();cerr<<"LIFT "<<u<<" base degree "<<bd[u]<<" normal degree "<<DD<<" terms "<<terms<<" seconds "<<sec<<"\n";meta<<u<<" "<<terms<<" "<<sec<<"\n";meta.flush();}
if(!meta)return 14;cerr<<"ALL LIFTED SOURCE BLOCKS PASS\n";
}
